// ❌ 버벅이는 버전
function App() {
  const [text, setText] = useState('')
  return (
    <div>
      <input value={text} onChange={e => setText(e.target.value)} />
      <HeavyList text={text} />  {/* 셀 1000개, 1ms씩 지연 */}
    </div>
  )
}
// 타이핑 → input & HeavyList 모두 SyncLane
// → 1초 동안 입력창 반응 없음 ❌

// ✅ 해결된 버전
function App() {
  const [text, setText] = useState('')
  const deferredText = useDeferredValue(text)  // TransitionLane으로

  return (
    <div>
      <input value={text} onChange={e => setText(e.target.value)} />
      <HeavyList text={deferredText} />
    </div>
  )
}
// input: SyncLane (즉시 반응) ✅
// HeavyList: TransitionLane (나중에 처리) ✅
// → 입력창 버벅임 없음

